how.forecast:
Forecast = actual of the month + targets of the days left
= {{actual}} + {{rest}} ({{days}} days left)
= {{forecast}}

how.best:
Best day = the complete day with the most bowls
= {{best}}
Lowest = the complete day with the fewest bowls
= {{worst}}

explain.day:
Actual = bowls of every shift = {{actual}}
Target = targets of the same shifts = {{target}}
Achievement = [[actual || target]] × 100
= [[{{actual}} || {{target}}]] × 100 = {{rate}}%

explain.typeCell:
Actual per day = [[actual total || days]] = [[{{a}} || {{n}}]] = {{avgA}}
Target per day = [[target total || days]] = [[{{t}} || {{n}}]] = {{avgT}}
Achievement = [[actual total || target total]] × 100 = [[{{a}} || {{t}}]] × 100 = {{rate}}%
